def run(frames, params):
    import numpy as np
    import json
    import math

    def obj(x):
        return x if isinstance(x, dict) else {}

    def arr(x):
        if isinstance(x, dict):
            x = x.get('values', x.get('data'))
        if x is None:
            return None
        try:
            a = np.asarray(x, dtype=float)
            return a if a.size else None
        except (TypeError, ValueError):
            return None

    def scalar(x):
        try:
            v = float(x)
            return v if math.isfinite(v) else None
        except (TypeError, ValueError, OverflowError):
            return None

    def parameter(k, default, upper):
        v = scalar(obj(params).get(k, default))
        return v if v is not None and 0 < v <= upper else default

    mt = parameter('marker_change_px', 2.0, 10000)
    rt = parameter('rgb_change', 0.02, 1)
    fs = list(frames)[-4:] if frames is not None else []
    fs = [obj(f) for f in fs]

    def quant(a):
        return np.quantile(a, [0.1, 0.5, 0.9]).tolist() if a.size else None

    def rotation(q):
        q = arr(q)
        if q is None or q.shape != (4,) or not np.isfinite(q).all():
            return None
        n = np.linalg.norm(q)
        if n < 1e-12:
            return None
        w, x, y, z = q / n
        return np.array([[1-2*(y*y+z*z), 2*(x*y-z*w), 2*(x*z+y*w)],
                         [2*(x*y+z*w), 1-2*(x*x+z*z), 2*(y*z-x*w)],
                         [2*(x*z-y*w), 2*(y*z+x*w), 1-2*(x*x+y*y)]])

    def pose(f):
        s = obj(f.get('state'))
        p = arr(s.get('eef_pose_wxyz'))
        if s.get('pose_frame') != 'world' or s.get('position_units') != 'm':
            return None
        if p is None or p.shape != (7,) or not np.isfinite(p).all():
            return None
        r = rotation(p[3:])
        return (p, r, s.get('eef_frame')) if r is not None else None

    def depth(x):
        a = arr(x)
        if a is not None and a.ndim == 3 and a.shape[2] == 1:
            a = a[:, :, 0]
        return a if a is not None and a.ndim == 2 else None

    def depth_stats(a):
        if a is None:
            return None
        good = np.isfinite(a) & (a > 0)
        return {'valid_fraction': float(good.mean()), 'q10_50_90': quant(a[good])}

    def rgb_pair(x, y):
        a, b = arr(x), arr(y)
        if a is None or b is None or a.shape != b.shape or a.ndim != 3 or a.shape[2] != 3:
            return None
        good = np.isfinite(a).all(axis=2) & np.isfinite(b).all(axis=2)
        if not good.any():
            return None
        av, bv = a[good], b[good]
        lo, hi = min(av.min(), bv.min()), max(av.max(), bv.max())
        if lo < 0 or hi > 255:
            return None
        scale = 1.0 if hi <= 1 else 255.0
        d = np.abs(av-bv).mean(axis=1) / scale
        changed = d > rt
        rc = np.argwhere(good)
        return {'mean_abs': float(d.mean()), 'fraction_above_threshold': float(changed.mean()),
                'centroid_rc': rc[changed].mean(axis=0).tolist() if changed.any() else None,
                'valid_fraction': float(good.mean()), 'inferred_scale': int(scale)}

    def markers(t):
        expected = {'marker_units': 'pixels', 'marker_coordinate_order': 'x,y',
                    'marker_origin': 'top_left', 'marker_axes': 'x_right_y_down'}
        if any(t.get(k) != v for k, v in expected.items()):
            return None, {'status': 'unknown_metadata'}
        r, d, c = [arr(t.get(k)) for k in ('marker_reference', 'marker_displacement', 'marker_current')]
        if r is None or d is None or r.ndim != 2 or r.shape[1] != 2 or d.shape != r.shape:
            return None, {'status': 'unknown_arrays'}
        good = np.isfinite(r).all(axis=1) & np.isfinite(d).all(axis=1)
        check = None
        if c is not None and c.shape == r.shape:
            good &= np.isfinite(c).all(axis=1)
            if good.any():
                check = float(np.max(np.linalg.norm(c[good]-r[good]-d[good], axis=1)))
                if check > 0.1:
                    return None, {'status': 'inconsistent_within_frame_rows', 'max_error_px': check}
        r, d = r[good], d[good]
        if not len(r):
            return None, {'status': 'no_finite_markers'}
        keys, inv = np.unique(np.round(r, 3), axis=0, return_inverse=True)
        vals = np.array([np.median(d[inv == k], axis=0) for k in range(len(keys))])
        unique_n = len(keys)
        if unique_n > 512:
            ix = np.linspace(0, unique_n-1, 512).astype(int)
            keys, vals = keys[ix], vals[ix]
        med = np.median(vals, axis=0)
        size = arr(t.get('image_size'))
        edge = None
        if size is not None and size.shape == (2,) and np.isfinite(size).all() and np.min(size) > 0:
            cur = keys + vals
            h, w = size
            edge = float(((cur[:, 0] < 0.02*w) | (cur[:, 0] >= 0.98*w) |
                          (cur[:, 1] < 0.02*h) | (cur[:, 1] >= 0.98*h)).mean())
        info = {'status': 'measured', 'unique_n': unique_n, 'used_n': len(keys),
                'duplicates_removed': len(r)-unique_n, 'median_xy_px': med.tolist(),
                'magnitude_q10_50_90_px': quant(np.linalg.norm(vals, axis=1)),
                'residual_p90_px': float(np.quantile(np.linalg.norm(vals-med, axis=1), 0.9)),
                'edge_fraction': edge, 'tracking_quality': scalar(t.get('tracking_quality'))}
        return (keys, vals), info

    def marker_delta(a, b, ta, tb):
        if a is None or b is None:
            return None
        sa, sb = arr(ta.get('image_size')), arr(tb.get('image_size'))
        if sa is None or sb is None or sa.shape != (2,) or sb.shape != (2,) or not np.array_equal(sa, sb):
            return None
        if not ta.get('reference_kind') or ta.get('reference_kind') != tb.get('reference_kind'):
            return None
        ra, da = a
        rb, db = b
        if min(len(ra), len(rb)) < 6:
            return None
        aa = np.linalg.norm(ra[:, None, :] - ra[None, :, :], axis=2)
        np.fill_diagonal(aa, np.inf)
        spacing = float(np.median(aa.min(axis=1)))
        gate = max(0.5, 0.2*spacing)
        dist = np.linalg.norm(ra[:, None, :] - rb[None, :, :], axis=2)
        j = dist.argmin(axis=1)
        back = dist.argmin(axis=0)
        i = np.arange(len(ra))
        keep = (back[j] == i) & (dist[i, j] <= gate)
        i, j = i[keep], j[keep]
        coverage = len(i) / max(len(ra), len(rb))
        if len(i) < 6 or coverage < 0.5:
            return {'status': 'insufficient_spatial_overlap', 'matched_n': len(i), 'coverage': coverage}
        dv = db[j] - da[i]
        med = np.median(dv, axis=0)
        mag = np.linalg.norm(dv, axis=1)
        return {'status': 'matched_reference_coordinates', 'matched_n': len(i), 'coverage': coverage,
                'match_p90_px': float(np.quantile(dist[i, j], 0.9)),
                'median_xy_px': med.tolist(), 'magnitude_q10_50_90_px': quant(mag),
                'residual_p90_px': float(np.quantile(np.linalg.norm(dv-med, axis=1), 0.9)),
                'above_threshold': bool(np.median(mag) > mt)}

    def tactile(f, side):
        return obj(obj(f.get('tactile')).get(side))

    def camera(f, name, hand):
        c = obj(obj(f.get('cameras')).get(name))
        cal = obj(c.get('calibration'))
        d = depth(c.get('depth'))
        unit = cal.get('depth_units', c.get('depth_units'))
        if d is None or unit not in ('m', 'mm'):
            return {'status': 'unknown_dense_depth_or_units'}
        if unit == 'mm':
            d = d * 0.001
        h, w = d.shape
        roi = arr(obj(obj(params).get('camera_rois')).get(name, [0, 0, 1, 1]))
        if roi is None or roi.shape != (4,) or not np.isfinite(roi).all() or np.any(roi < 0) or np.any(roi > 1):
            return {'status': 'invalid_roi'}
        r0, c0 = int(roi[0]*h), int(roi[1]*w)
        r1, c1 = int(np.ceil(roi[2]*h)), int(np.ceil(roi[3]*w))
        if r1 <= r0 or c1 <= c0:
            return {'status': 'empty_roi'}
        patch = d[r0:r1, c0:c1]
        out = {'status': 'measured', 'roi_rc': [r0, c0, r1, c1], 'depth_m': depth_stats(patch),
               'visible_plane': None}
        k = arr(cal.get('intrinsics'))
        rot = rotation(cal.get('quaternion_wxyz'))
        if cal.get('camera_convention') != 'ros_optical' or k is None or k.shape != (3, 3):
            return out
        if not np.isfinite(k).all() or abs(np.linalg.det(k)) < 1e-12:
            return out
        if cal.get('height') != h or cal.get('width') != w:
            out['status'] = 'depth_measured_calibration_size_mismatch'
            return out
        stride = max(1, int(np.ceil(np.sqrt(patch.size/1600.0))))
        yy, xx = np.meshgrid(np.arange(r0, r1, stride), np.arange(c0, c1, stride), indexing='ij')
        z = d[yy, xx]
        valid = np.isfinite(z) & (z > 0)
        if valid.sum() < 30:
            return out
        rays = np.column_stack((xx[valid], yy[valid], np.ones(valid.sum()))) @ np.linalg.inv(k).T
        if np.any(np.abs(rays[:, 2]) < 1e-12):
            return out
        p = rays * (z[valid] / rays[:, 2])[:, None]
        use = np.ones(len(p), dtype=bool)
        try:
            for _ in range(4):
                center = np.median(p[use], axis=0)
                _, sv, vt = np.linalg.svd(p[use]-center, full_matrices=False)
                normal = vt[-1]
                res = np.abs((p-center) @ normal)
                use = res <= max(0.003, float(np.quantile(res, 0.7)))
            center = p[use].mean(axis=0)
            _, sv, vt = np.linalg.svd(p[use]-center, full_matrices=False)
            normal = vt[-1]
            res = np.abs((p-center) @ normal)
            inlier = res <= 0.003
            fraction = float(inlier.mean())
            if fraction < 0.6 or inlier.sum() < 30 or sv[1] < 1e-5:
                return out
            if normal @ center > 0:
                normal = -normal
            nw = rot @ normal if rot is not None else None
            out['visible_plane'] = {'normal_optical': normal.tolist(),
                'normal_world': nw.tolist() if nw is not None else None,
                'support_fraction': fraction, 'sample_n': len(p),
                'residual_p90_m': float(np.quantile(res[inlier], 0.9)),
                'hand_z_unoriented_angle_deg': float(np.degrees(np.arccos(np.clip(abs(nw @ hand[1][:, 2]), 0, 1)))) if nw is not None and hand is not None else None}
        except np.linalg.LinAlgError:
            pass
        return out

    out = {'frames': [], 'latest': {}, 'intervals': [], 'window_peak': None,
           'applicability': {'temporal': len(fs) >= 2, 'absolute_contact': 'unknown',
             'notes': ['Reference may already be loaded; zero RGB change does not imply no contact.',
                       'Marker vectors are image pixels; bilateral signs do not define a world direction.',
                       'Plane is a dominant visible patch, never a concealed axis or clearance.',
                       'Spread and coverage are descriptive, not calibrated confidence.']}}
    if not fs:
        out['applicability']['temporal'] = False
        return out
    for i, f in enumerate(fs):
        step = scalar(f.get('step'))
        out['frames'].append({'index': i, 'step': int(step) if step is not None else None})
    poses = [pose(f) for f in fs]
    fields = []
    for f in fs:
        fields.append({s: markers(tactile(f, s)) for s in ('left', 'right')})
    last = fs[-1]
    out['latest']['frame'] = len(fs)-1
    out['latest']['hand_z_world'] = poses[-1][1][:, 2].tolist() if poses[-1] is not None else None
    out['latest']['tactile'] = {}
    for s in ('left', 'right'):
        t = tactile(last, s)
        kind = t.get('reference_kind')
        out['latest']['tactile'][s] = {'markers': fields[-1][s][1],
            'reference_kind': str(kind)[:60] if kind is not None else None,
            'rgb_vs_reference': rgb_pair(t.get('rgb'), t.get('reference_rgb')),
            'native_camera_depth_mm': depth_stats(depth(t.get('depth'))) if t.get('depth_units') == 'mm' else None}
    out['latest']['cameras'] = {n: camera(last, n, poses[-1]) for n in ('head', 'wrist')}
    peak = -1.0
    for i in range(1, len(fs)):
        a, b = fs[i-1], fs[i]
        rec = {'frames': [i-1, i], 'simulation_dt_s': None, 'measured_hand_delta': None, 'tactile': {}}
        ta, tb = scalar(a.get('simulation_time_s')), scalar(b.get('simulation_time_s'))
        if ta is not None and tb is not None and tb > ta:
            rec['simulation_dt_s'] = tb-ta
        pa, pb = poses[i-1], poses[i]
        if pa is not None and pb is not None and pa[2] == pb[2]:
            qa, qb = pa[0][3:], pb[0][3:]
            dot = abs(float((qa/np.linalg.norm(qa)) @ (qb/np.linalg.norm(qb))))
            rec['measured_hand_delta'] = {'world_xyz_m': (pb[0][:3]-pa[0][:3]).tolist(),
                'rotation_deg': float(np.degrees(2*np.arccos(np.clip(dot, 0, 1))))}
        ds = {}
        for s in ('left', 'right'):
            aa, bb = tactile(a, s), tactile(b, s)
            md = marker_delta(fields[i-1][s][0], fields[i][s][0], aa, bb)
            rgb = rgb_pair(aa.get('rgb'), bb.get('rgb'))
            dd = None
            da, db = depth(aa.get('depth')), depth(bb.get('depth'))
            if aa.get('depth_units') == bb.get('depth_units') == 'mm' and da is not None and db is not None and da.shape == db.shape:
                good = np.isfinite(da) & np.isfinite(db) & (da > 0) & (db > 0)
                if good.any():
                    dd = {'common_valid_fraction': float(good.mean()),
                          'abs_change_p90_mm': float(np.quantile(np.abs(db[good]-da[good]), 0.9))}
            rec['tactile'][s] = {'markers': md, 'rgb': rgb, 'native_depth': dd}
            if md is not None and md.get('status') == 'matched_reference_coordinates':
                ds[s] = md
        rec['bilateral'] = None
        if len(ds) == 2:
            l, r = np.array(ds['left']['median_xy_px']), np.array(ds['right']['median_xy_px'])
            strength = float(np.mean([ds[s]['magnitude_q10_50_90_px'][1] for s in ('left', 'right')]))
            rgb_available = all(rec['tactile'][s]['rgb'] is not None for s in ('left', 'right'))
            rgb_changed = all(rec['tactile'][s]['rgb']['fraction_above_threshold'] > 0.01 for s in ('left', 'right')) if rgb_available else None
            rec['bilateral'] = {'opposite_image_x_change': bool(l[0]*r[0] < 0 and min(abs(l[0]), abs(r[0])) > mt),
                'both_marker_fields_changed': all(ds[s]['above_threshold'] for s in ('left', 'right')),
                'both_rgb_changed': rgb_changed,
                'mean_median_change_px': strength}
            if strength > peak:
                peak = strength
                out['window_peak'] = {'frames': [i-1, i], 'mean_median_change_px': strength,
                    'opposite_image_x_change': rec['bilateral']['opposite_image_x_change']}
        out['intervals'].append(rec)

    def clean(x):
        if isinstance(x, dict):
            return {str(k): clean(v) for k, v in x.items()}
        if isinstance(x, (list, tuple)):
            return [clean(v) for v in x]
        if isinstance(x, (bool, np.bool_)):
            return bool(x)
        if isinstance(x, (int, np.integer)):
            return int(x)
        if isinstance(x, (float, np.floating)):
            return round(float(x), 6) if math.isfinite(float(x)) else None
        return x

    out = clean(out)
    out['omitted_interval_count'] = 0
    while len(json.dumps(out, allow_nan=False)) >= 5900 and len(out['intervals']) > 1:
        out['intervals'].pop(0)
        out['omitted_interval_count'] += 1
    if len(json.dumps(out, allow_nan=False)) >= 5900:
        for c in out['latest']['cameras'].values():
            c.pop('visible_plane', None)
        out['plane_details_omitted'] = True
    if len(json.dumps(out, allow_nan=False)) >= 5900:
        out['latest'].pop('cameras', None)
        out['camera_details_omitted'] = True
    if len(json.dumps(out, allow_nan=False)) >= 5900:
        out['omitted_interval_count'] += len(out['intervals'])
        out['intervals'] = []
    return out
